package co.edu.uco.seguridad.pdp.authorization.application.usecase.impl;
import co.edu.uco.seguridad.pdp.authorization.application.primaryport.request.ListApplicationRoleAssignmentsRequest; import co.edu.uco.seguridad.pdp.authorization.application.rule.validator.PrincipalMustBeApplicationAdministratorValidator; import co.edu.uco.seguridad.pdp.authorization.application.usecase.ListApplicationRoleAssignmentsUseCase; import co.edu.uco.seguridad.pdp.assignments.application.primaryport.request.ListApplicationAssignmentsPageRequest; import co.edu.uco.seguridad.pdp.assignments.application.primaryport.response.AssignmentResponse; import co.edu.uco.seguridad.pdp.assignments.application.usecase.ListApplicationRoleAssignmentsPageUseCase; import co.edu.uco.seguridad.pdp.commons.model.ResultPage; import reactor.core.publisher.Mono;
public final class ListApplicationRoleAssignmentsUseCaseImpl implements ListApplicationRoleAssignmentsUseCase {private final PrincipalMustBeApplicationAdministratorValidator gate;private final ListApplicationRoleAssignmentsPageUseCase assignments;public ListApplicationRoleAssignmentsUseCaseImpl(PrincipalMustBeApplicationAdministratorValidator gate,ListApplicationRoleAssignmentsPageUseCase assignments){this.gate=gate;this.assignments=assignments;}public Mono<ResultPage<AssignmentResponse>> execute(ListApplicationRoleAssignmentsRequest i){return gate.execute(i.administration()).then(Mono.defer(()->assignments.execute(new ListApplicationAssignmentsPageRequest(i.administration().tenantId(),i.administration().applicationId(),i.window()))));}}
